// ARM_Serial_Wire_Debug_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module ARM_Serial_Wire_Debug_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic  c_cdbgpwrupack,
  input logic  c_csyspwrupack,
  input logic [31:0] c_ap_wdata,
  input logic  c_ap_write,
  input logic [7:0] c_ap_sel,
  input logic [5:0] c_ap_addr,
  input logic [31:0] c_ap_rdata,
  input logic  c_ap_err,
  input logic  c_ap_busy,
  input logic  c_lockout,
  input logic  c_cdbgpwrupreq,
  input logic  c_csyspwrupreq,
  input logic  c_ap_req,
  input logic  c_ap_done,
  input logic  c_line_reset,
  input logic  c_proto_err,
  input logic  c_ack_wait,
  input logic  c_ack_fault,
  input logic  c_ap_abort
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 11;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:10];          // model of every stored word
  logic [6:0] m_set;                // interrupt bits set this clock
  logic m_state_APREQ;          // full / valid pulse / available
  logic m_state_APRESP;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_line_reset) m_set[0] = 1'b1;
    if (c_proto_err) m_set[1] = 1'b1;
    if (c_ack_wait) m_set[2] = 1'b1;
    if (c_ack_fault) m_set[3] = 1'b1;
    if (c_ap_abort) m_set[4] = 1'b1;
    if (c_ap_req && !m_state_APREQ) m_set[5] = 1'b1;
    if (c_ap_req && m_state_APREQ && (m_rd && m_map && m_idx == 7)) m_set[5] = 1'b1;
    if (c_ap_req && m_state_APREQ && !(m_rd && m_map && m_idx == 7)) m_set[6] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_state_APREQ <= 0;
      m_state_APRESP <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h7F;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h3;
      if (c_ap_req && (!m_state_APREQ || (m_rd && m_map && m_idx == 7))) begin
        m_w[6] <= (32'(c_ap_wdata[31:0]) << 0);
        m_w[7] <= (32'(c_ap_write) << 0) | (32'(c_ap_sel[7:0]) << 1) | (32'(c_ap_addr[5:0]) << 9);
        m_state_APREQ <= 1;
      end else if ((m_rd && m_map && m_idx == 7)) m_state_APREQ <= 0;
      if (m_wr && m_map && m_idx == 8) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 9) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'h1;
      m_state_APRESP <= m_wr && m_map && m_idx == 9;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h53570200;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_APREQ});
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return (32'(c_ap_busy) << 0) | (32'(c_lockout) << 1) | (32'(c_cdbgpwrupreq) << 2) | (32'(c_csyspwrupreq) << 3);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][6:0] & m_w[2][6:0]))
  `SVA_INV(a_core_cdbgpwrupack, c_cdbgpwrupack == m_w[5][0:0])
  `SVA_INV(a_core_csyspwrupack, c_csyspwrupack == m_w[5][1:1])
  `SVA_INV(a_core_ap_rdata, c_ap_rdata == m_w[8][31:0])
  `SVA_INV(a_core_ap_err, c_ap_err == m_w[9][0:0])
  `SVA_INV(a_core_ap_done, c_ap_done == m_state_APRESP)
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_cdbgpwrupack == 1'h0 && c_csyspwrupack == 1'h0 && c_ap_rdata == 32'h0 && c_ap_err == 1'h0 && !c_ap_done)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_PWR, m_rd && m_map && m_idx == 5)
  `FC(wr_PWR, m_wr && m_map && m_idx == 5)
  `FC(rd_APREQ0, m_rd && m_map && m_idx == 6)
  `FC(wr_APREQ0, m_wr && m_map && m_idx == 6)
  `FC(rd_APREQ1, m_rd && m_map && m_idx == 7)
  `FC(wr_APREQ1, m_wr && m_map && m_idx == 7)
  `FC(rd_APRESP0, m_rd && m_map && m_idx == 8)
  `FC(wr_APRESP0, m_wr && m_map && m_idx == 8)
  `FC(rd_APRESP1, m_rd && m_map && m_idx == 9)
  `FC(wr_APRESP1, m_wr && m_map && m_idx == 9)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 10)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 10)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_LINE_RESET_set, m_set[0])
  `FC(irq_LINE_RESET_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_LINE_RESET_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_LINE_RESET_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_PROTO_ERR_set, m_set[1])
  `FC(irq_PROTO_ERR_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_PROTO_ERR_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_PROTO_ERR_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_WAIT_set, m_set[2])
  `FC(irq_WAIT_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_WAIT_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_WAIT_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_FAULT_set, m_set[3])
  `FC(irq_FAULT_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_FAULT_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_FAULT_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(irq_ABORT_set, m_set[4])
  `FC(irq_ABORT_cleared, m_w[1][4] && m_wr && m_map && m_idx == 1 && PWDATA[4] && PSTRB[0])
  `FC(irq_ABORT_masked, m_w[1][4] && !m_w[2][4])
  `FC(irq_ABORT_drives_pin, m_w[1][4] && m_w[2][4] && irq)
  `FC(irq_APREQ_AVAIL_set, m_set[5])
  `FC(irq_APREQ_AVAIL_cleared, m_w[1][5] && m_wr && m_map && m_idx == 1 && PWDATA[5] && PSTRB[0])
  `FC(irq_APREQ_AVAIL_masked, m_w[1][5] && !m_w[2][5])
  `FC(irq_APREQ_AVAIL_drives_pin, m_w[1][5] && m_w[2][5] && irq)
  `FC(irq_APREQ_OVF_set, m_set[6])
  `FC(irq_APREQ_OVF_cleared, m_w[1][6] && m_wr && m_map && m_idx == 1 && PWDATA[6] && PSTRB[0])
  `FC(irq_APREQ_OVF_masked, m_w[1][6] && !m_w[2][6])
  `FC(irq_APREQ_OVF_drives_pin, m_w[1][6] && m_w[2][6] && irq)
  `FC(APREQ_capture, c_ap_req && !m_state_APREQ)
  `FC(APREQ_overflow, c_ap_req && m_state_APREQ && !(m_rd && m_map && m_idx == 7))
  `FC(APREQ_pop, m_rd && m_map && m_idx == 7 && m_state_APREQ)
  `FC(APREQ_read_empty, m_rd && m_map && m_idx == 7 && !m_state_APREQ)
  `FC(APREQ_pop_and_capture, c_ap_req && m_state_APREQ && m_rd && m_map && m_idx == 7)
  `FC(APRESP_commit, m_state_APRESP)
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind ARM_Serial_Wire_Debug_apb ARM_Serial_Wire_Debug_apb_sva u_apb_sva (.*);
